class MemoryManager:
    def __init__(self, size):
        self.memory = [0] * size
        self.allocated = [False] * size
        self.size = size

    def allocate(self, size):
        for i in range(self.size - size + 1):
            if all(not self.allocated[j] for j in range(i, i + size)):
                for j in range(i, i + size):
                    self.allocated[j] = True
                return i
        return -1

    def copy(self, src_start, dst_start, size):
        if src_start < 0 or dst_start < 0 or src_start + size > self.size or dst_start + size > self.size:
            return False
        for i in range(size):
            self.memory[dst_start + i] = self.memory[src_start + i]
        return True

    def free(self, start, size):
        for i in range(start, start + size):
            if i < self.size:
                self.allocated[i] = False

    def print_memory(self):
        print("Memory state:", self.memory)
        print("Allocated state:", self.allocated)

# Simulate memory management
memory_manager = MemoryManager(20)

# Allocate two fragments of size 10 each
fragment1_start = memory_manager.allocate(10)
fragment2_start = memory_manager.allocate(10)

print(f"Allocated fragment 1 at index {fragment1_start}")
print(f"Allocated fragment 2 at index {fragment2_start}")

# Copy content from first fragment to second
memory_manager.copy(fragment1_start, fragment2_start, 10)

print("Copied content from first fragment to second fragment")

# Free the first fragment
memory_manager.free(fragment1_start, 10)
print("Freed first fragment")

# Free the second fragment
memory_manager.free(fragment2_start, 10)
print("Freed second fragment")

# Print final memory state
memory_manager.print_memory()
